#include <iostream>
using namespace std;

// 定义计算函数
double calculate(double num1, double num2, char operatorSign) {
    switch (operatorSign) {
        case '+':
            return num1 + num2;
        case '-':
            return num1 - num2;
        case '*':
            return num1 * num2;
        case '/':
            // 处理除数为0的情况
            if (num2 == 0) {
                cout << "Error: Division by zero is not allowed." << endl;
                return 0;
            }
            return num1 / num2;
        default:
            cout << "Error: Invalid operator." << endl;
            return 0;
    }
}

